import json
for name in ['packet','authoritative-research']:
 d=json.load(open('input/'+name+'.json'))
 print('\n'+name)
 def tree(x,p='',depth=0):
  if isinstance(x,dict):
   for k,v in x.items():
    z=p+'.'+k
    print(z, type(v).__name__, len(json.dumps(v,ensure_ascii=False)), ('len='+str(len(v))) if isinstance(v,(dict,list)) else '')
    if depth<2 and isinstance(v,dict):tree(v,z,depth+1)
  elif isinstance(x,list):
   for i,v in enumerate(x): print(p+'['+str(i)+']',type(v).__name__,len(json.dumps(v,ensure_ascii=False)))
 tree(d)
 if name=='packet':a=d
 else:b=d
print('\nSHARED TOP-LEVEL EXACT EQUALITY')
for k in sorted(a.keys()|b.keys()): print(k,'same' if a.get(k)==b.get(k) else 'DIFF')
print('\nEVIDENCE ENTRY SHAPES')
for i,v in enumerate(b['evidence']):
 print(i,{k:(str(x)[:300] if not isinstance(x,(dict,list)) else {'type':type(x).__name__,'len':len(x)}) for k,x in v.items()})
PY","max_output_tokens":10000}));

